-- =============================================================================
-- Source:   The synthetic district programme reports.
-- License:  Generated by this project. Carries no external licence.
-- Format:   SQLite database, read through a JDBC datasource.
-- Docs:     scripts/make_synthetic.py, src/programme_checks.py
--
-- WHY THIS SOURCE IS HERE
--   It gives the unified layer a third connector type (a database table)
--   next to the REST tables and the file tables, and it gives the checks
--   something to be measured against: the generated rows carry planted
--   contradictions and an equal number of clean controls.
--
--   It is registered in its OWN Lightning database, and every row carries
--   is_synthetic=true, so it can never be unioned with real evidence by
--   accident.
--
-- WHERE THE DATABASE FILE HAS TO BE
--   The driver container has to be able to open the file. The shared
--   storage is the place, and it works:
--     python3 scripts/make_synthetic.py
--     docker cp data/synthetic_programme_reports.db \
--       zetaris-driver-1:/home/zetaris/customer-data/shared/cross_examiner_synthetic.db
--
--   The engine image ships the SQLite driver:
--     /home/zetaris/zetaris-ndp-driver/lib/org.xerial.sqlite-jdbc-3.46.0.0.jar
--
-- Before running:
--   docker exec zetaris-driver-1 ls -la /home/zetaris/customer-data/shared
--   docker exec zetaris-driver-1 ls /home/zetaris/zetaris-ndp-driver/lib/org.xerial.sqlite-jdbc-*.jar
--
-- Status: live-tested on the local instance (2026-10-26). The datasource
-- was created, the table was registered, and the query returns 181 rows.
-- =============================================================================

CREATE LIGHTNING DATABASE SYNTHETIC_PROGRAMME_REPORTS DESCRIBE BY "SYNTHETIC district programme reports";

CREATE DATASOURCE synthetic_programme_db DESCRIBE BY "Synthetic programme report database" OPTIONS (
  jdbcdriver "org.sqlite.JDBC",
  jdbcurl "jdbc:sqlite:/home/zetaris/customer-data/shared/synthetic_programme_reports.db"
);

REGISTER DATASOURCE TABLE synthetic_programme_reports FROM synthetic_programme_db;

CREATE SCHEMASTORE VIEW synthetic_programme_reports_table WITH CONTAINER cross_examiner AS
SELECT
    district,
    country,
    antigen,
    year,
    measure,
    CAST(value_percent AS DOUBLE) AS value_percent,
    numerator,
    denominator,
    source_id AS source_name,
    source_ref AS source_url,
    is_synthetic,
    notes
FROM synthetic_programme_db.synthetic_programme_reports;

-- The verification query: every row must be marked synthetic.
SELECT COUNT(*) AS total,
       SUM(CASE WHEN is_synthetic THEN 1 ELSE 0 END) AS synthetic_rows
FROM cross_examiner.synthetic_programme_reports_table;

